   337→            <button id="copy-email-btn" class="btn btn-primary">Email to FDO/FCIM</button>
   338→            <button id="reset-btn" class="btn btn-danger">Reset Form</button>
   339→            
   340→            <a href="cia.html" class="btn btn-home">RETURN TO START</a>
   341→        </div>
