   353→    <script>
   354→        document.addEventListener('DOMContentLoaded', function() {
   355→            const copyEmailBtn = document.getElementById('copy-email-btn');
   356→            const resetBtn = document.getElementById('reset-btn');
   357→            const hiddenCopyArea = document.getElementById('hidden-copy-area');
   358→            const successMessage = document.getElementById('success-message');
   359→            
   360→            // Load previously saved values if they exist
   361→            for(let i = 1; i <= 10; i++) {
   362→                const item = document.getElementById('item' + i);
   363→                if(sessionStorage.getItem('action_item' + i)) {
   364→                    item.value = sessionStorage.getItem('action_item' + i);
   365→                }
   366→                
   367→                // Save values to session storage on change
   368→                item.addEventListener('change', function() {
   369→                    sessionStorage.setItem('action_item' + i, this.value);
   370→                });
   371→            }
   372→            
   373→            copyEmailBtn.addEventListener('click', function() {
   374→                // Gather all checklist data
   375→                let checklistData = '';
   376→                checklistData += '-------KIDNAP BLACKMAIL/EXTORTION - CALL HANDLER ACTIONS CHECKLIST-------\n\n';
   377→                
   378→                // Get each item and its status
   379→                const items = [
   380→                    'A specialist officer will recall using the code word. If no code word is provided then no information should be given.',
   381→                    'Tell them to come up with a credible cover story if they are questioned as to why their phone is engaged (ie speaking to the bank or a friend etc).',
   382→                    'Explain to the caller they MUST maintain secrecy even to family and friends.',
   383→                    'Keep a record of any calls received (times, dates, tel numbers).',
   384→                    'Complete a 1471 enquiry after any calls if they have no identification facility on their phone.',
   385→                    'Keep the phone line free for any further contact from the offenders/police.',
   386→                    'Do not attempt to record any conversations as this may alert the offenders.',
   387→                    'Advice the caller that any direct approach to them by the Police will be by plain clothes officers who will produce ID. This may cause a delay in our response.',
   388→                    'If not already given, provide the caller with a secure contact number 0161 856 1884 to enable them to provide any further information should they be made aware of any.',
   389→                    'Once all above actions have been completed, make HAC aware and ask that the call associated with this report is emailed to the FIM asap.'
   390→                ];
   391→                
   392→                for(let i = 0; i < items.length; i++) {
   393→                    const status = document.getElementById('item' + (i + 1)).value || 'Not Completed';
   394→                    checklistData += (i + 1) + '. ' + items[i] + '\n';
   395→                    checklistData += '   Status: ' + status + '\n\n';
   396→                }
   397→                
   398→                // Copy to clipboard first
   399→                hiddenCopyArea.value = checklistData;
   400→                
   401→                function afterCopy() {
   402→                    successMessage.innerHTML = 'Information copied and email opened!';
   403→                    successMessage.style.display = 'block';
   404→                    setTimeout(() => successMessage.style.display = 'none', 3000);
   405→                }
   406→
   407→                // Create concise but complete email body
   408→                let emailBodyData = 'KIDNAP CHECKLIST:\n\n';
   409→                for(let i = 0; i < items.length; i++) {
   410→                    const status = document.getElementById('item' + (i + 1)).value || 'Not Completed';
   411→                    // Use shorter descriptions but keep key words
   412→                    let shortDesc = '';
   413→                    switch(i) {
   414→                        case 0: shortDesc = 'Specialist officer recall with code word'; break;
   415→                        case 1: shortDesc = 'Cover story for engaged phone'; break;
   416→                        case 2: shortDesc = 'Maintain secrecy to family/friends'; break;
   417→                        case 3: shortDesc = 'Record all calls (times/dates/numbers)'; break;
   418→                        case 4: shortDesc = 'Complete 1471 enquiry'; break;
   419→                        case 5: shortDesc = 'Keep phone line free'; break;
   420→                        case 6: shortDesc = 'Do not record conversations'; break;
   421→                        case 7: shortDesc = 'Plain clothes officer ID warning'; break;
   422→                        case 8: shortDesc = 'Provide secure contact number 0161 856 1884'; break;
   423→                        case 9: shortDesc = 'Make HAC aware - email to FIM'; break;
   424→                        default: shortDesc = items[i].substring(0, 40) + '...'; break;
   425→                    }
   426→                    emailBodyData += `${i + 1}. ${shortDesc}: ${status}\n`;
   427→                }
   428→                emailBodyData += '\nFull details on clipboard if needed.';
   429→
   430→                // Create mailto link
   431→                const subject = encodeURIComponent('**URGENT**KIDNAP INCIDENT - Call Handlers Actions Checklist**');
   432→                let mailtoLink = `mailto:fim@gmp.police.uk,fcim@gmp.police.uk?subject=${subject}&body=${encodeURIComponent(emailBodyData)}`;
   433→                
   434→                try {
   435→                    navigator.clipboard.writeText(checklistData).then(() => {
   436→                        afterCopy();
   437→                        window.location.href = mailtoLink;
   438→                    }, fallbackCopy);
   439→                } catch {
   440→                    fallbackCopy();
   441→                }
   442→
   443→                function fallbackCopy() {
   444→                    hiddenCopyArea.select();
   445→                    if (document.execCommand('copy')) {
   446→                        afterCopy();
   447→                        window.location.href = mailtoLink;
   448→                    } else {
   449→                        alert('Unable to copy to clipboard. Please copy manually.');
   450→                    }
   451→                }
   452→            });
   453→            
   454→            resetBtn.addEventListener('click', function() {
   455→                // Reset all select elements
   456→                for(let i = 1; i <= 10; i++) {
   457→                    document.getElementById('item' + i).value = '';
   458→                    sessionStorage.removeItem('action_item' + i);
   459→                }
   460→            });
   461→        });
   462→    </script>
   463→</body>
   464→</html>

